return items.map(item => {
  const json = item.json;
  const tipoFormatado = json.tipo === 'retorno' ? 'Retorno' : 'Primeira Consulta';
  const partesData = (json.data || '').split('-');
  const dataFormatada = partesData.length === 3 ? `${partesData[2]}/${partesData[1]}/${partesData[0]}` : json.data;

  const assunto = `Lembrete: Sua consulta na Clínica Bem Viver amanhã às ${json.hora}`;
  const corpoHtml = `
    <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 24px; border: 1px solid #e2e8f0; border-radius: 8px; color: #1e293b;">
      <div style="display: flex; align-items: center; margin-bottom: 20px;">
        <h2 style="color: #0d9488; margin: 0;">Clínica Bem Viver</h2>
      </div>
      <p>Olá, <strong>${json.pacienteNome}</strong>!</p>
      <p>Este é um lembrete da sua consulta médica agendada para amanhã:</p>

      <div style="background-color: #f0fdfa; border-left: 4px solid #0d9488; border-radius: 4px; padding: 16px; margin: 20px 0;">
        <p style="margin: 6px 0;"><strong>Data:</strong> ${dataFormatada}</p>
        <p style="margin: 6px 0;"><strong>Horário:</strong> ${json.hora}</p>
        <p style="margin: 6px 0;"><strong>Profissional:</strong> ${json.profissionalNome}</p>
        <p style="margin: 6px 0;"><strong>Especialidade:</strong> ${json.especialidade}</p>
        <p style="margin: 6px 0;"><strong>Tipo:</strong> ${tipoFormatado}</p>
      </div>

      <h4 style="color: #334155; margin-bottom: 8px;">Orientações Importantes:</h4>
      <ul style="color: #64748b; font-size: 14px; line-height: 1.6; padding-left: 20px; margin-top: 0;">
        <li>Por favor, chegue com 15 minutos de antecedência.</li>
        <li>Apresente documento oficial com foto e carteira de identificação.</li>
        <li>Traga seus exames e receitas de medicamentos em uso.</li>
        <li>Se precisar remarcar ou cancelar, acesse o portal com antecedência mínima de 2 horas.</li>
      </ul>

      <hr style="border: none; border-top: 1px solid #e2e8f0; margin: 24px 0;" />
      <p style="color: #94a3b8; font-size: 12px; text-align: center; margin: 0;">
        Clínica Bem Viver • Atendimento humanizado e cuidado integral com sua saúde.
      </p>
    </div>
  `;

  return {
    json: {
      ...json,
      assunto,
      corpoHtml
    }
  };
});
